// --- Passing validations ---

test("Basic object with properties and required", function() {
  const schema = {
    type: 'object',
    properties: {
      name: { type: 'string' },
      age: { type: 'number' },
      email: { type: 'string' },
      status: { type: 'string' },
      score: { type: 'number' },
